:14:27.028515+00:00"}, {"id": 173, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 174, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 175, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 176, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 177, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 178, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 179, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 180, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 181, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 182, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 183, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 184, "updated_at": "2026-10-31T14:14:27.028515+00:00"}, {"id": 185, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 186, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 187, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 188, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 189, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 190, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 191, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 192, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 193, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 194, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 195, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 196, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 197, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 198, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 199, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 200, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 201, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 202, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 203, "updated_at": "2026-10-31T14:14:37.644807+00:00"}, {"id": 210, "updated_at": "2026-11-01T22:48:50.283223+00:00"}, {"id": 211, "updated_at": "2026-11-01T22:48:50.283223+00:00"}, {"id": 212, "updated_at": "2026-11-01T22:48:50.283223+00:00"}, {"id": 213, "updated_at": "2026-11-01T22:48:50.283223+00:00"}, {"id": 214, "updated_at": "2026-11-01T22:48:50.283223+00:00"}, {"id": 215, "updated_at": "2026-11-01T22:48:50.283223+00:00"}]}$guards$::jsonb;
begin
 if (select count(*) from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1) > 0 then
   if (select count(*) from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1 and entity_kind='node') <> 110 then raise exception 'Incomplete prior publication'; end if;
   return;
 end if;

 if (select count(*) from atlas_team_nodes where project_id='ftc-main' and team_id=1 and department_id=2) <> 110
 or exists(select 1 from jsonb_to_recordset(guards->'nodes') as g(id bigint, updated_at timestamptz)
 left join atlas_team_nodes t on t.id=g.id and t.project_id='ftc-main' and t.team_id=1 where t.id is null or t.updated_at is distinct from g.updated_at)
 then raise exception 'Source nodes changed since review snapshot'; end if;

 if (select count(*) from atlas_team_node_code_snippets where project_id='ftc-main' and team_id=1 and node_id=any(source_ids)) <> 459
 or exists(select 1 from jsonb_to_recordset(guards->'codes') as g(id bigint, updated_at timestamptz)
 left join atlas_team_node_code_snippets t on t.id=g.id and t.project_id='ftc-main' and t.team_id=1 where t.id is null or t.updated_at is distinct from g.updated_at)
 then raise exception 'Source codes changed since review snapshot'; end if;

 if (select count(*) from atlas_team_node_media where project_id='ftc-main' and team_id=1 and node_id=any(source_ids)) <> 69
 or exists(select 1 from jsonb_to_recordset(guards->'media') as g(id bigint, updated_at timestamptz)
 left join atlas_team_node_media t on t.id=g.id and t.project_id='ftc-main' and t.team_id=1 where t.id is null or t.updated_at is distinct from g.updated_at)
 then raise exception 'Source media changed since review snapshot'; end if;

 if (select count(*) from atlas_team_roadmaps where project_id='ftc-main' and team_id=1 and department_id=2) <> 23
 or exists(select 1 from jsonb_to_recordset(guards->'roadmaps') as g(id bigint, updated_at timestamptz)
 left join atlas_team_roadmaps t on t.id=g.id and t.project_id='ftc-main' and t.team_id=1 where t.id is null or t.updated_at is distinct from g.updated_at)
 then raise exception 'Source roadmaps changed since review snapshot'; end if;

 if (select count(*) from atlas_team_roadmap_steps where project_id='ftc-main' and team_id=1 and true) <> 209
 or exists(select 1 from jsonb_to_recordset(guards->'steps') as g(id bigint, updated_at timestamptz)
 left join atlas_team_roadmap_steps t on t.id=g.id and t.project_id='ftc-main' and t.team_id=1 where t.id is null or t.updated_at is distinct from g.updated_at)
 then raise exception 'Source steps changed since review snapshot'; end if;

 if exists(select 1 from atlas_team_node_media where project_id='ftc-main' and team_id=1 and node_id=any(source_ids) and storage_path is not null) then raise exception 'Private media requires explicit publication handling'; end if;
 if exists(select 1 from atlas_team_node_files where project_id='ftc-main' and team_id=1 and node_id=any(source_ids)) then raise exception 'Files require publication handling'; end if;
 if not exists(select 1 from atlas_nodes where id=999032 and project_id='ftc-main' and md5(content)='d885b9870ce35f5dc0ee4f0e7a7c1ee5') then raise exception 'Existing global introduction changed'; end if;

 for r in select n.*, c.slug as category_slug, d.slug as difficulty_slug from atlas_team_nodes n
 left join atlas_team_categories c on c.id=n.team_category_id
 left join atlas_team_difficulties d on d.id=n.team_difficulty_id
 where n.project_id='ftc-main' and n.team_id=1 and n.id=any(source_ids) order by n.id loop
  if r.id=11 then
   target:=999032;
   update atlas_nodes set title=r.title,tag=r.tag,x=r.x,y=r.y,width=r.width,height=r.height,content=r.content,content_format=r.content_format,
   category_id=(select id from atlas_categories where project_id='ftc-main' and slug=r.category_slug limit 1),
   difficulty_id=(select id from atlas_difficulties where project_id='ftc-main' and slug=r.difficulty_slug limit 1) where id=target;
  else
   insert into atlas_nodes(project_id,title,tag,x,y,width,height,content,content_format,category_id,difficulty_id)
   values('ftc-main',r.title,r.tag,r.x,r.y,r.width,r.height,r.content,r.content_format,
    (select id from atlas_categories where project_id='ftc-main' and slug=r.category_slug limit 1),
    (select id from atlas_difficulties where project_id='ftc-main' and slug=r.difficulty_slug limit 1)) returning id into target;
  end if;
  insert into atlas_node_departments(project_id,node_id,department_id) values('ftc-main',target,2) on conflict do nothing;
  insert into atlas_global_publication_map values('ftc-main',1,'node',r.id,target,now());
 end loop;
 for r in select c.*, p.public_id as public_node from atlas_team_node_code_snippets c join atlas_global_publication_map p on p.project_id=c.project_id and p.source_team_id=c.team_id and p.entity_kind='node' and p.source_id=c.node_id where c.project_id='ftc-main' and c.team_id=1 order by c.id loop
  insert into atlas_node_code_snippets(project_id,node_id,language,title,description,code,sort_order)
  values('ftc-main',r.public_node,r.language,r.title,r.description,r.code,r.sort_order) returning id into target;
  insert into atlas_global_publication_map values('ftc-main',1,'code',r.id,target,now());
 end loop;
 for r in select c.*, p.public_id as public_node from atlas_team_node_media c join atlas_global_publication_map p on p.project_id=c.project_id and p.source_team_id=c.team_id and p.entity_kind='node' and p.source_id=c.node_id where c.project_id='ftc-main' and c.team_id=1 order by c.id loop
  insert into atlas_node_media(project_id,node_id,media_type,external_url,mime_type,file_size,title,caption,sort_order)
  values('ftc-main',r.public_node,r.media_type,r.external_url,r.mime_type,r.file_size,r.title,r.caption,r.sort_order) returning id into target;
  insert into atlas_global_publication_map values('ftc-main',1,'media',r.id,target,now());
 end loop;
 -- Each document is rewritten once from its reviewed source, never by cascading numeric substitutions.
 for r in select p.public_id,n.content,n.id from atlas_team_nodes n join atlas_global_publication_map p on p.project_id=n.project_id and p.source_team_id=n.team_id and p.entity_kind='node' and p.source_id=n.id where n.project_id='ftc-main' and n.team_id=1 loop
  document:=r.content;
  -- Temporary tokens avoid source/public ID collisions during replacement.
  for m in select * from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1 and entity_kind in ('code','media') loop
   document:=replace(document,format('data-atlas-embed="%s" data-atlas-id="%s"',m.entity_kind,m.source_id),format('data-atlas-embed="%s" data-atlas-id="PUBLIC_%s"',m.entity_kind,m.public_id));
  end loop;
  document:=replace(document,'data-atlas-id="PUBLIC_','data-atlas-id="');
  for m in select * from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1 and entity_kind='node' order by length(source_id::text) desc loop
   document:=regexp_replace(document,'/#team-1-node-'||m.source_id||'(["<>[:space:]]|$)','/node/'||m.public_id||'\1','g');
  end loop;
  update atlas_nodes set content=document where id=r.public_id;
 end loop;
 for r in select e.*,a.public_id as public_source,b.public_id as public_target from atlas_team_edges e
 join atlas_global_publication_map a on a.project_id=e.project_id and a.source_team_id=e.team_id and a.entity_kind='node' and a.source_id=e.source_id
 join atlas_global_publication_map b on b.project_id=e.project_id and b.source_team_id=e.team_id and b.entity_kind='node' and b.source_id=e.target_id
 where e.project_id='ftc-main' and e.team_id=1 order by e.id loop
  insert into atlas_edges(project_id,source_id,target_id,label,control_x,control_y,control_points) values('ftc-main',r.public_source,r.public_target,r.label,r.control_x,r.control_y,r.control_points) returning id into target;
  insert into atlas_global_publication_map values('ftc-main',1,'edge',r.id,target,now());
 end loop;
 for r in select * from atlas_team_roadmaps where project_id='ftc-main' and team_id=1 and department_id=2 order by id loop
  insert into atlas_roadmaps(project_id,title,slug,description,department_id,is_active,sort_order)
  values('ftc-main',r.title,'infotronx-programming-r'||r.id,'InfotronX #19119 · '||replace(replace(r.description,'Team-only','Public'),'din InfotronX',''),2,r.is_active,r.sort_order) returning id into target;
  insert into atlas_global_publication_map values('ftc-main',1,'roadmap',r.id,target,now());
 end loop;
 for r in select s.*,a.public_id as public_roadmap,b.public_id as public_node from atlas_team_roadmap_steps s
 join atlas_global_publication_map a on a.project_id=s.project_id and a.source_team_id=s.team_id and a.entity_kind='roadmap' and a.source_id=s.roadmap_id
 join atlas_global_publication_map b on b.project_id=s.project_id and b.source_team_id=s.team_id and b.entity_kind='node' and b.source_id=s.node_id
 where s.project_id='ftc-main' and s.team_id=1 order by s.id loop
  insert into atlas_roadmap_steps(project_id,roadmap_id,node_id,position,note,is_optional) values('ftc-main',r.public_roadmap,r.public_node,r.position,r.note,r.is_optional) returning id into target;
  insert into atlas_global_publication_map values('ftc-main',1,'step',r.id,target,now());
 end loop;
 -- The complete roadmap is the shared reading checklist for this collection.
 insert into atlas_roadmaps(project_id,title,slug,description,department_id,is_active,sort_order)
 values('ftc-main','Roadmap global · FTC Programming','infotronx-programming-complet',
 'Parcurge toate cele 110 lecții sau alege un capitol. Colecție îngrijită de InfotronX #19119.',2,true,-10)
 returning id into canonical_roadmap;
 insert into atlas_roadmap_steps(project_id,roadmap_id,node_id,position)
 select project_id,canonical_roadmap,public_id,row_number() over(order by source_id)
 from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1 and entity_kind='node';
 insert into atlas_roadmap_progress(project_id,roadmap_id,node_id,user_id,completed_at)
 select reads.project_id,canonical_roadmap,p.public_id,reads.user_id,reads.read_at
 from atlas_team_node_reads reads join atlas_global_publication_map p
 on p.project_id=reads.project_id and p.source_team_id=reads.team_id and p.entity_kind='node' and p.source_id=reads.node_id
 where reads.project_id='ftc-main' and reads.team_id=1 on conflict do nothing;
 if exists (
  select 1 from atlas_nodes n
  join atlas_global_publication_map p on p.project_id=n.project_id and p.entity_kind='node' and p.public_id=n.id
  cross join lateral regexp_matches(n.content,'data-atlas-embed="(code|media)" data-atlas-id="([0-9]+)"','g') as match
  where p.source_team_id=1 and n.project_id='ftc-main' and (
   (match[1]='code' and not exists(select 1 from atlas_node_code_snippets c where c.id=match[2]::bigint and c.node_id=n.id))
   or (match[1]='media' and not exists(select 1 from atlas_node_media asset where asset.id=match[2]::bigint and asset.node_id=n.id))
  )
 ) then raise exception 'Public document contains an invalid attachment'; end if;
 if (select count(*) from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1 and entity_kind='node')<>110 then raise exception 'Publication node count mismatch'; end if;
 if (select count(*) from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1 and entity_kind='code')<>459 then raise exception 'Publication code count mismatch'; end if;
 if (select count(*) from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1 and entity_kind='media')<>69 then raise exception 'Publication media count mismatch'; end if;
end $publication$;
set constraints all immediate;
select entity_kind,count(*) from atlas_global_publication_map where project_id='ftc-main' and source_team_id=1 group by entity_kind order by entity_kind;
commit;
